  "",
  ".input-btn {",
  "  width: 38px;",
  "  height: 38px;",
  "  min-width: 38px;",
  "  border-radius: 50%;",
  "  border: none;",
  "  display: flex;",
  "  align-items: center;",
  "  justify-content: center;",
  "  cursor: pointer;",
  "  transition: all var(--transition);",
  "  font-size: 1rem;",
  "  padding: 0;",
  "}",
  "#mic {",
  "  background: transparent;",
  "  color: var(--text-muted);",
  "}",
  "#mic svg {",
  "  display: block;",
  "}",
  "#mic:hover {",
  "  color: var(--accent);",
  "  background: var(--accent-glow);",
  "}",
  "#mic.listening {",
  "  background: var(--accent);",
  "  color: #fff;",
  "  animation: pulse 1.2s ease-in-out infinite;",
  "}",
  "#mic.unsupported {",
  "  display: none;",
  "}",
  "#send,",
  "#logs-send {",
  "  background: var(--accent);",
  "  color: #fff;",
  "}",
  "#send:hover,",
  "#logs-send:hover {",
  "  background: var(--accent-hover);",
  "}",
  "#send:disabled,",
  "#logs-send:disabled {",
  "  opacity: 0.4;",
  "  cursor: not-allowed;",
  "}",
  "",
  "@keyframes pulse {",
  "  0%,",
  "  100% {",
  "    box-shadow: 0 0 0 0 var(--accent-glow);",
  "  }",
  "  50% {",
  "    box-shadow: 0 0 0 10px transparent;",
  "  }",
  "}",
  "",
  "/* ── Status Bar ──────────────────────────────────────────── */",
  ".statusbar {",
  "  display: flex;",
  "  align-items: center;",
  "  justify-content: center;",
  "  gap: 1.25rem;",
  "  padding: 0.5rem 0 0.25rem;",
  "  font-size: 0.7rem;",
  "  color: var(--text-dim);",
