  "  height: 6px;",
  "  border-radius: 50%;",
  "  background: var(--success);",
  "  margin-right: 0.3rem;",
  "}",
  "",
  "/* ── Pages ───────────────────────────────────────────────── */",
  ".page {",
  "  display: none;",
  "  flex: 1;",
  "  flex-direction: column;",
  "  overflow: hidden;",
  "  min-height: 0;",
  "}",
  ".page.active {",
  "  display: flex;",
  "}",
  "",
  ".page-placeholder {",
