  "  font-weight: 700;",
  "  color: var(--text);",
  "  font-family: ui-monospace, monospace;",
  "}",
  "",
  "/* Terminal */",
  ".terminal {",
  "  flex: 1;",
  "  display: flex;",
  "  flex-direction: column;",
  "  background: var(--bg-card);",
  "  border: 1px solid var(--border);",
  "  border-radius: 12px;",
  "  overflow: hidden;",
  "  min-height: 0;",
  "}",
  ".terminal-titlebar {",
  "  display: flex;",
  "  align-items: center;",
