  ".terminal-dots span:nth-child(2) {",
  "  background: #febc2e;",
  "}",
  ".terminal-dots span:nth-child(3) {",
  "  background: #28c840;",
  "}",
  ".terminal-title {",
  "  font-family: ui-monospace, monospace;",
  "  font-size: 0.75rem;",
  "  color: var(--text-muted);",
