  ".log-level-warn {",
  "  color: #febc2e;",
  "}",
  ".log-level-error {",
  "  color: #ff5f57;",
  "}",
  ".log-level-debug {",
  "  color: var(--text-dim);",
  "}",
  ".log-component {",
  "  color: var(--accent);",
  "}",
  ".log-msg {",
  "  color: var(--text);",
  "}",
  ".log-separator {",
