  "                    <polyline points=\"14 2 14 8 20 8\" />",
  "                    <line x1=\"16\" y1=\"13\" x2=\"8\" y2=\"13\" />",
  "                    <line x1=\"16\" y1=\"17\" x2=\"8\" y2=\"17\" />",
  "                    <polyline points=\"10 9 9 9 8 9\" /></svg",
  "                ></span>",
  "                <span data-i18n=\"status.logs\">Logs</span>",
  "              </button>",
  "            </div>",
  "          </div>",
  "          <div class=\"settings-content\">",
  "            <div class=\"settings-header\">",
  "              <h1><span data-i18n=\"status.header\">System </span><strong data-i18n=\"status.headerStrong\">Status</strong></h1>",
  "              <p class=\"settings-header-sub\" data-i18n=\"status.headerSub\">",
  "                Geraetezustand, Pflege, Verbesserungsvorschlaege und Aktivitaetsprotokoll.",
  "              </p>",
  "            </div>",
  "",
  "            <!-- System Health -->",
  "            <div class=\"settings-section active\" id=\"status-health\">",
  "              <div class=\"backlog-header\">",
  "                <div class=\"settings-section-title\" data-i18n=\"status.health\">System Health</div>",
  "                <button",
  "                  type=\"button\"",
  "                  class=\"backlog-add-btn\"",
  "                  id=\"health-refresh-btn\"",
  "                  onclick=\"loadSystemHealth(true)\"",
  "                >",
  "                  <svg",
  "                    width=\"14\"",
  "                    height=\"14\"",
  "                    viewBox=\"0 0 24 24\"",
  "                    fill=\"none\"",
  "                    stroke=\"currentColor\"",
  "                    stroke-width=\"2.5\"",
